import asyncio
import logging
import sys

from aiogram import Bot, Dispatcher, html
from aiogram.client.default import DefaultBotProperties
from aiogram.enums import ParseMode
from aiogram.filters import CommandStart
from aiogram.types import Message, ReplyKeyboardMarkup, KeyboardButton

TOKEN = ("8290403667:AAH-gsZiw4PI17fTdv3OV-2wIFk9zD6Bf_E")

dp = Dispatcher()

main_menu = ReplyKeyboardMarkup(
    keyboard=[
        [KeyboardButton(text="🍔 menu"), KeyboardButton(text="🥤 yaxna Ichimliklar")],
        [KeyboardButton(text="🛒 qo'shimcha xarid"), KeyboardButton(text="📞 yordam")]
    ],
    resize_keyboard=True
)

@dp.message(CommandStart())
async def command_start_handler(message: Message):

    user_name = message.from_user.full_name
    await message.answer(
        f"Assalomu alaykum, {html.bold(user_name)}! EVOS botiga xush kelibsiz.\nNimadan boshlaymiz?",
        reply_markup=main_menu
    )

@dp.message()
async def menu_handler(message: Message):

    text = message.text

    if text == "🍔 menu":
        await message.answer_photo(photo="data:image/png;base64," \
        "" \
        "", caption="https://evos.uz/")
    elif text == "🥤 yaxna ichimliklar":
        await message.answer("Katalog: Coca-Cola, Fanta, Choy")
    elif text == "🛒 qo'shimcha xarid":
        await message.answer("qo'shimcha xarid qilishni xozircha iloji yo'q!")
    elif text == "📞 yordam":
        await message.answer("Bizning koll-markaz: +998 71 200 00 00")
    else:
        await message.answer("Iltimos, pastdagi menyu tugmalaridan birini tanlang.")







































async def main():
    bot = Bot(token=TOKEN, default=DefaultBotProperties(parse_mode=ParseMode.HTML))

    await dp.start_polling(bot)

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO, stream=sys.stdout)
    asyncio.run(main())